const DATE_TWISTS=[
 {id:"rain",t:f=>`จู่ ๆ ฝนก็เทลงมา คุณกับ${f.name}วิ่งไปหลบใต้ชายคาร้านเดียวกัน ไหล่ชิดกันโดยไม่ได้ตั้งใจ`,
  choice:[{t:"ถอดเสื้อคลุมให้เธอคลุมหัว",sc:3,rep:"…ขอบคุณค่ะ ตัวคุณเปียกแทนแล้วนะ"},{t:"ชวนวิ่งฝ่าฝนกลับไปด้วยกัน",sc:2,rep:"บ้าที่สุด! แต่ก็… สนุกดีนะ"}]},
 {id:"fan",t:f=>`เด็กผู้หญิงคนหนึ่งวิ่งเข้ามาขอลายเซ็น${f.name} "หนูดูไฟต์พี่ทุกครั้งเลยค่ะ!"`,
  choice:[{t:"ถ่ายรูปให้ทั้งสองคน",sc:3,rep:"มีแฟนคลับด้วยแฮะ… ตื่นเต้นจนมือสั่นเลย"},{t:"บอกเด็กว่าพี่เขากำลังพักผ่อนอยู่",sc:-1,rep:"…ไม่เป็นไรหรอก เซ็นให้แป๊บเดียวเอง"}]},
 {id:"vendor",t:f=>`แม่ค้าข้างทางทักว่า "แฟนกันเหรอจ๊ะ น่ารักจัง เอาพวงมาลัยไปฝากกันสักพวงไหม"`,
  choice:[{t:"ซื้อพวงมาลัยให้เธอ",sc:3,rep:"มะ— ไม่ใช่แฟนนะคะป้า! …แต่พวงมาลัยหอมดีนะ"},{t:"ปฏิเสธพลางหัวเราะ",sc:1,rep:"ป้าเขาแซวไปเรื่อยแหละ… ใช่ไหมคะ"}]},
 {id:"cat",t:f=>`แมวส้มตัวอ้วนเดินมาคลอเคลียขา${f.name} แล้วนอนหงายท้องโชว์ต่อหน้าทั้งสองคน`,
  choice:[{t:"นั่งลงลูบแมวด้วยกัน",sc:2,rep:"ดูสิ มันชอบคุณด้วยนะ แปลกจัง แมวไม่ค่อยชอบใครง่าย ๆ"},{t:"แซวว่าแมวหน้าเหมือนเธอ",sc:-1,rep:"หน้าเหมือนตรงไหน! …อ้วนตรงนี้เหรอ!"}]},
 {id:"rival",t:f=>`ระหว่างทาง คุณเจอนักมวยค่ายพยัคฆ์ทองสองคนเดินสวนมา พวกเขาหัวเราะเยาะ "ผู้จัดการพาลูกค่ายเที่ยว ไม่ซ้อมเหรอ"`,
  choice:[{t:"ยืนข้าง ๆ เธอเงียบ ๆ ไม่ตอบโต้",sc:2,rep:"ขอบคุณที่ไม่ปล่อยให้หนูยืนคนเดียวนะคะ ไว้เจอกันบนเวที"},{t:"ตอบกลับแรง ๆ",sc:0,rep:"ใจเย็นค่ะ… แต่ก็สะใจดีนะ"}]},
];
function dateTwist(G,f,D,look){const r=srand(G,(f.twists||[]).length*13+f.id.charCodeAt(0));if(r>.4)return [];f.twists=f.twists||[];
  const pool=DATE_TWISTS.filter(x=>!f.twists.includes(x.id));if(!pool.length)return [];const T=pool[Math.floor(srand(G,f.id.charCodeAt(1)+97)*pool.length)];f.twists.push(T.id);
  return [{n:"nar",t:T.t(f)},{choice:T.choice.map(c=>({t:c.t,fx:()=>{D.score+=c.sc;},then:[{n:f.id,f:c.sc>=2?"flustered":c.sc<0?"pout":"happy",l:look,t:c.rep}]}))}];}

