// v1.15: the camp talks about last week's big fight
const LOSS_SELF={kati:"…หนูขอโทษนะคะ ซ้อมมาขนาดนั้นแล้วยัง…",mali:"ฮือ… มะลิเตะไม่ถึงเลยสักลูก",rin:"ข้อมูลฉันผิดตรงไหน… ฉันต้องรู้ให้ได้"};
// v1.22.1: rotate so the morning-after talk doesn't repeat word for word
const WIN_TEASE={kati:[a=>`เห็นไหม! ${a}เมื่อคืนสุดยอดไปเลย ค่ายเราไม่ธรรมดา!`,a=>`${a}! หนูดูจากมุมเวทีแล้วขนลุกเลย ซ้อมด้วยกันอีกนะ`,a=>`ค่ายเราชนะติดกันแล้วนะ ${a} คุณปู่ต้องยิ้มอยู่แน่ ๆ`],
  mali:[a=>`${a}เมื่อคืนเท่มาก~ มะลิตะโกนจนเสียงแหบเลย!`,a=>`ฉลองด้วยขนมครกถาดใหญ่เลย! ${a}จ่ายนะ ฮิ ๆ`,a=>`${a}~ ป้าแต๋วบอกจะตั้งชื่อเมนูตามเธอแล้วนะ!`],
  rin:[a=>`ฉันจดไว้แล้วค่ะ ความแม่นของ${a}เมื่อคืนสูงที่สุดของปี`,a=>`${a} ยกสองเธอคุมระยะได้ดีกว่าค่าเฉลี่ยมากค่ะ ฉันมีกราฟ`,a=>`ชนะครั้งนี้เพิ่มโอกาสเข้าท็อปสี่ของ${a}ไปอีกนิดค่ะ`]};
const pickR=(L,G,k=0)=>{if(!Array.isArray(L))return L;G.rot=G.rot||{};const n=G.rot[k]=(G.rot[k]||0)+1;return L[n%L.length];};
const WIN_SELF={kati:["แต่ยังไม่พอหรอกค่ะ! เป้าหมายของหนูยังอยู่ข้างหน้าอีกไกล","ขอบคุณค่ะ… แต่หนูยังเห็นจุดพลาดตัวเองอีกเยอะเลย","ชนะแล้ว! คืนนี้ขอนอนเร็วหน่อย พรุ่งนี้ตีห้าเหมือนเดิมค่ะ"],
  mali:["เย้~ แต่มะลิยังไม่อิ่มนะ! ขอไฟต์ต่อไปเลย","ขาบวมนิดหน่อย แต่คุ้ม~ ใครทำขนมครกให้มะลิหน่อย!","เมื่อคืนมะลิเห็นแม่ยิ้มในแชตด้วยนะ~"],
  rin:["ชนะตามที่คำนวณไว้ค่ะ …แต่ส่วนต่างคะแนนยังแคบเกินไป ต้องดีกว่านี้","ผลออกมาตามโมเดลค่ะ ฉันจะปรับโมเดลให้แม่นกว่านี้อีก","…ดีใจค่ะ ฉันแค่แสดงออกไม่เป็น"]};
const COACH_WIN=["ชนะแล้วอย่าเหลิง พรุ่งนี้ตีห้าเหมือนเดิม","ดี แต่ยกสองการ์ดตก ครูเห็นนะ","ปู่ชัยดูอยู่ ชนะแบบนี้ท่านคงพอใจ","กินให้อิ่ม นอนให้พอ แล้วกลับมาซ้อม","ชนะได้ก็แพ้ได้ อย่าลืมว่าวันนี้ได้มาเพราะอะไร"];
function aftermathSteps(G,L){const me=G.F[L.a],op=G.F[L.b];const mates=roster(G).filter(f=>f.id!==me.id);const m=mates[0];const steps=[];
  if(L.win==="A"){steps.push({n:"nar",t:`เช้าวันต่อมา ข่าว${me.name}เอาชนะ${op.name}ไปทั่วหมู่บ้าน`});
    if(m)steps.push({n:m.id,f:"happy",l:"train",t:WIN_TEASE[m.id]?pickR(WIN_TEASE[m.id],G,"t_"+m.id)(me.name):`ยินดีด้วยนะ ${me.name}!`});
    if(op.id==="ploy")steps.push({n:me.id,f:"flustered",l:"train",t:"หนู… ชนะพี่พลอยได้จริง ๆ เหรอ ตีห้าทุกวันมันไม่เสียเปล่าเลย"});
    else steps.push({n:me.id,f:"happy",l:"train",t:WIN_SELF[me.id]?pickR(WIN_SELF[me.id],G,"s_"+me.id):"แต่ยังไม่พอหรอก!"});
    if(coachOn())steps.push({n:"coach",t:pickR(COACH_WIN,G,"c")});}
  else{if(op.id==="ploy")steps.push({n:"nar",t:"คืนนั้น พลอยเดินลงจากเวทีไปโดยไม่หันกลับมามองเลยสักครั้ง",show:[{id:"ploy",back:true}]});
    steps.push({n:"nar",t:`หลังแพ้${op.name} ${me.name}นั่งเงียบอยู่มุมห้องซ้อมทั้งเช้า`});
    steps.push({n:me.id,f:"sad",l:"train",t:op.id==="ploy"&&me.id==="kati"?"พี่พลอยยังไกลเกินไป… หรือหนูไม่มีทางไปถึงจริง ๆ":LOSS_SELF[me.id]||"…ขอโทษนะ"});
    if(m)steps.push({n:m.id,f:"sad",l:"train",t:m.id==="rin"?`${me.name} ยกสองเธอนำอยู่นะ ฉันมีตัวเลขยืนยัน ไม่ได้แย่อย่างที่คิด`:m.id==="mali"?`${me.name}~ มะลิทำขนมครกไว้ให้แล้ว กินก่อนแล้วค่อยเศร้าต่อนะ`:`${me.name}… ตีห้าพรุ่งนี้ หนูรอซ้อมด้วยนะ`});
    steps.push({choice:[{t:"แพ้ครั้งนี้บอกเราว่าต้องแก้อะไร ไปแก้ด้วยกัน",fx:G=>{add(G,me.id,"morale",6);add(G,me.id,"trust",3);},then:[{n:me.id,f:"happy",l:"train",t:{kati:"…ค่ะ! ครั้งหน้าหนูจะไม่แพ้แบบเดิมอีก",mali:"อื้อ! ครั้งหน้ามะลิเตะให้ถึงทุกลูกเลย!",rin:"ฉันจะทำตารางแก้จุดอ่อนให้เสร็จคืนนี้ค่ะ"}[me.id]||"…ค่ะ!"}]},
      {t:"วันนี้พักก่อน ไปกินอะไรอร่อย ๆ กัน",fx:G=>{add(G,me.id,"bond",4);add(G,me.id,"morale",3);me.fatigue=Math.max(0,me.fatigue-5);},then:[{n:me.id,f:"flustered",l:"casual",t:{kati:"…ขอบคุณนะคะ วันนี้หนูขอแค่นี้ก็พอ",mali:"หมูกระทะได้ไหม~ มะลิหายเศร้าทันทีเลย",rin:"…ไม่มีเหตุผลทางสถิติที่ของอร่อยจะช่วย แต่ฉันจะไปค่ะ"}[me.id]||"…ขอบคุณนะ"}]}]});}
  return steps;}
// v1.16: year-end hooks — beating them is what makes Ploy and Fah look at Sirichai
function season2Hooks(G,key){if(key==="bankrupt")return [];const S=[];
  const beatPloy=G.champ.A==="kati"&&G.finalists.A.includes("ploy"),beatFah=G.champ.B==="mali"&&G.finalists.B.includes("fah");
  if(beatPloy||G.F.ploy.bond>=50){S.push({n:"nar",bg:"camp",t:"สามวันหลังไฟนอล มีคนมายืนหน้าประตูค่ายตั้งแต่ตีห้า ในกางเกงมวยสีม่วงที่ทุกคนจำได้ ราวกับพร้อมจะซ้อมได้ทันที",show:[{id:"ploy",back:true}]},
    ...(beatPloy?[{n:"ploy",f:"sad",l:"casual",t:"ฉันแพ้เป็นครั้งแรกในรอบสามปี… แล้วก็เพิ่งรู้ว่าตลอดเวลาที่ผ่านมา ฉันไม่เคยพยายามจริง ๆ เลย"},
      {n:"ploy",f:"flustered",l:"casual",t:"เถ้าแก่ปลดฉันจากกัปตันแล้ว ค่ายศิริชัย… ยังรับคนที่อยากเริ่มนับหนึ่งใหม่ไหม"}]:
     [{n:"ploy",f:"flustered",l:"casual",t:"ได้ยินว่าค่ายศิริชัยรับสมัครนักมวยปีหน้า… ฉันขอคุยเรื่องสัญญาได้ไหม"}]),
    {choice:[{t:"ประตูค่ายนี้เปิดรอเธออยู่แล้ว",fx:G=>{add(G,"ploy","bond",6);G.s2=Object.assign(G.s2||{},{ploy:"yes"});},then:[{n:"ploy",f:"happy",l:"casual",t:"…ขอบคุณ งั้นพรุ่งนี้ตีห้า ฉันจะมาวิ่งกับกะทิ"}]},
     {t:"คิดให้ดีก่อน ปีหน้าค่อยคุยกันอีกที",fx:G=>{G.s2=Object.assign(G.s2||{},{ploy:"later"});},then:[{n:"ploy",f:"happy",l:"casual",t:"ยุติธรรมดี… ฉันจะกลับมาใหม่"}]}]});}
  if(beatFah||G.F.fah.bond>=50)S.push({n:"fah",f:beatFah?"angry":"happy",l:"casual",t:beatFah?"เด็กไชยานั่นเตะฟ้าจนหูอื้อเลยนะ! …ปีหน้าฟ้าขอมาซ้อมที่นี่ ไม่งั้นแก้มือไม่ได้สักที":"เฮ้ ปีหน้าฟ้าขอย้ายมาค่ายนายได้ไหม! ที่พยัคฆ์ทองมันน่าเบื่อแล้ว"});
  if(S.length)S.push({n:"nar",t:"ปีหน้า ค่ายศิริชัยอาจมีนักมวยมากกว่าที่ใครคิด…"});
  return S;}
