// ---------- v1.22 personal ending: the person closest to you gets the last word of the season ----------
const PERSONAL_END={
 kati:[{n:"nar",t:"คืนสุดท้ายของปี กะทิพาคุณขึ้นไปบนหลังคาค่าย มองเห็นไฟเมืองเชียงใหม่ทั้งเมือง"},{n:"kati",f:"happy",l:"casual",t:"ปีที่แล้วตอนนี้ หนูนั่งตรงนี้คนเดียว คิดว่าค่ายจะต้องปิด"},{n:"kati",f:"flustered",l:"casual",t:"ปีนี้มีคุณนั่งข้าง ๆ… หนูว่าคุณปู่คงยิ้มอยู่บนนั้นค่ะ"}],
 mali:[{n:"nar",t:"มะลิลากคุณไปตลาดนัดคืนสุดท้ายของปี ยืนอยู่หน้าร้านขนมครกร้านเล็ก ๆ"},{n:"mali",f:"happy",l:"casual",t:"วันหนึ่งมะลิจะเปิดร้านแบบนี้ ชื่อร้าน 'ขนมครกแชมป์' ฮิ ๆ"},{n:"mali",f:"flustered",l:"casual",t:"คุณต้องเป็นลูกค้าคนแรกนะคะ… ไม่สิ เป็นหุ้นส่วนเลยดีกว่า~"}],
 rin:[{n:"nar",t:"รินยื่นแฟ้มหนาให้คุณ หน้าปกเขียนว่า 'แผนสามปี ค่ายศิริชัย'"},{n:"rin",f:"happy",l:"casual",t:"ฉันวางแผนไว้ถึงปีที่สาม ทุกหน้ามีชื่อคุณอยู่ค่ะ"},{n:"rin",f:"flustered",l:"casual",t:"…ไม่ใช่แค่เพราะคุณเป็นผู้จัดการนะคะ ตัวแปรนี้ฉันยังหาคำอธิบายไม่ได้"}],
 ploy:[{n:"nar",t:"หลังนัดชิง พลอยรออยู่ที่ลานจอดรถ ผ้าพันมือยังไม่ได้แกะ"},{n:"ploy",f:"happy",l:"casual",t:"ปีนี้พี่ได้เรียนรู้ว่าการชกให้สนุกเป็นยังไง เพราะค่ายคุณ"},{n:"ploy",f:"flustered",l:"casual",t:"ปีหน้าเราจะเจอกันอีก จะในฐานะคู่แข่ง… หรืออะไรอย่างอื่น ก็แล้วแต่คุณ"}],
 fah:[{n:"nar",t:"ฟ้าโผล่มาพร้อมมอเตอร์ไซค์คันเก่า 'ขึ้นมา ยายรอกินข้าวอยู่'"},{n:"fah",f:"pout",l:"casual",t:"ยายบอกว่าคืนสิ้นปีต้องกินข้าวกับคนสำคัญ ฟ้าเลย… เอ่อ… ยายบังคับ!"},{n:"fah",f:"flustered",l:"casual",t:"…ปีหน้าก็มากินอีกนะ ไม่ได้ขอร้องนะ แค่บอก"}]};
function personalEnding(G){let id=G.romance;if(!id){const c=["kati","mali","rin","ploy","fah"].filter(k=>G.F[k]&&G.F[k].met&&(G.F[k].bond||0)>=40).sort((a,b)=>G.F[b].bond-G.F[a].bond);id=c[0];}
  const base=id&&PERSONAL_END[id]?PERSONAL_END[id]:[];if(G.romance===id&&LOVER_END[id])return [...base,...LOVER_END[id]];
  const pr=G.promise?Object.keys(G.promise).find(k=>PROMISE_END[k]):null;return [...base,...(pr&&pr!==id?[]:pr?PROMISE_END[pr]:[])];}

